#include <stdio.h>
#include <stdlib.h>

static long long *bit;
static int n;

void bit_add(int idx, long long delta) {
    for (; idx <= n; idx += idx & -idx) {
        bit[idx] += delta;
    }
}

long long bit_sum(int idx) {
    long long res = 0;
    for (; idx > 0; idx -= idx & -idx) {
        res += bit[idx];
    }
    return res;
}

int main(void) {
    int q;
    if (scanf("%d %d", &n, &q) != 2) return 0;

    bit = (long long *)calloc(n + 1, sizeof(long long));
    int *a = (int *)malloc((n + 1) * sizeof(int));

    for (int i = 1; i <= n; i++) {
        scanf("%d", &a[i]);
        bit_add(i, a[i]);
    }

    for (int i = 0; i < q; i++) {
        int type;
        scanf("%d", &type);

        if (type == 0) {
            int k, p;
            scanf("%d %d", &k, &p);
            long long delta = (long long)p - a[k];
            a[k] = p;
            bit_add(k, delta);
        } else {
            int k;
            scanf("%d", &k);
            printf("%lld\n", bit_sum(k));
        }
    }

    free(a);
    free(bit);
    return 0;
}
